 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the longest straight run and its same-colored perpendicular run,
    # which together form the pointer's L corner.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            color, start = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if color != bg and c - start >= 5:
                runs.append((c - start, color, r, start, c - 1, 0))
    for c in range(w):
        r = 0
        while r < h:
            color, start = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if color != bg and r - start >= 5:
                runs.append((r - start, color, start, c, c, 1))
    if not runs:
        return out
    _, signal, r0, c0, c1, orientation = max(runs)
    if orientation == 0:
        # Horizontal arm: identify a vertical run of the same color touching
        # an endpoint; this is the elbow of the L.
        corners = [(r0, c) for c in (c0, c1)
                   if 0 <= c < w and any(grid[r][c] == signal for r in range(h))]
        if not corners:
            return out
        er, ec = min(corners, key=lambda p: sum(grid[r][p[1]] == signal for r in range(h)), reverse=True)
        vertical = [r for r in range(h) if grid[r][ec] == signal]
        if not vertical:
            return out
        er = min(vertical, key=lambda r: abs(r - r0))
        horizontal_side = -1 if ec == c0 else 1
        vertical_side = -1 if er == min(vertical) and max(vertical) > er else (1 if er == min(vertical) else -1)
    else:
        # Vertical arm: find a touching horizontal run and its corner.
        ec = c0
        same_rows = [r for r in range(h) if grid[r][ec] == signal]
        if not same_rows:
            return out
        er = min(same_rows, key=lambda r: abs(r - r0))
        row_cells = [c for c in range(w) if grid[er][c] == signal]
        if not row_cells:
            return out
        horizontal_side = -1 if min(row_cells) < ec else 1
        vertical_side = -1 if er == min(same_rows) else 1

    # The intended target lies diagonally beyond the two arms (the open
    # quadrant of the L). Select the largest object in that quadrant.
    open_dr, open_dc = -vertical_side, -horizontal_side
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if color != signal:
                cr = sum(x for x, _ in cells) / len(cells)
                cc = sum(y for _, y in cells) / len(cells)
                if (cr - er) * open_dr > 0 and (cc - ec) * open_dc > 0:
                    comps.append(cells)
    if not comps:
        return out
    target = max(comps, key=len)
    for r, c in target:
        out[r][c] = signal
    return out
