def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Detect the long L-shaped signal from the longest non-background
    # horizontal and vertical runs of the same color that meet at an endpoint.
    hruns = []
    vruns = []
    for r in range(h):
        c = 0
        while c < w:
            color, start = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if color != bg and c - start >= 5:
                hruns.append((c - start, color, r, start, c - 1))
    for c in range(w):
        r = 0
        while r < h:
            color, start = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if color != bg and r - start >= 5:
                vruns.append((r - start, color, start, r - 1, c))
    choices = []
    for hl, color, hr, hc0, hc1 in hruns:
        for vl, vcolor, vr0, vr1, vc in vruns:
            if color != vcolor:
                continue
            if vc in (hc0, hc1) and hr in (vr0, vr1):
                choices.append((hl + vl, color, hr, vc))
    if not choices:
        return out
    _, signal, er, ec = max(choices)

    # The L points to the nearest separate object in the northwest diagonal
    # sector from its elbow. Recolor that entire connected object to the
    # signal color, preserving all unrelated cells.
    components = []
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if color != signal:
                cr = sum(rr for rr, _ in cells) / len(cells)
                cc = sum(cc for _, cc in cells) / len(cells)
                if cr < er and cc < ec:
                    distance = (er - cr) + (ec - cc)
                    components.append((distance, cells))
    if components:
        _, target = min(components, key=lambda item: item[0])
        for r, c in target:
            out[r][c] = signal
    return out
